//! Integration tests against the ORIGINAL Modlight server running on this Mac
//! (`http://127.0.0.1:8420`, see `docs/PORT.md` section 4).
//!
//! The credentials come from `_wzorzec/qa-accounts.env`, found by walking up from this
//! crate, or from the file named by `MODLIGHT_QA_ENV`. Without that file the tests say
//! so and pass (a checkout elsewhere has no reference server); with it, the server has
//! to be up and every check has to hold.
//!
//! Every test works on its own uniquely named folders and freshly generated bytes, so
//! they can run in parallel and against a library other agents are also using.

use std::collections::HashMap;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::path::PathBuf;
use std::time::Duration;

use modlight_api::signin::{self, LoopbackListener};
use modlight_api::{
    Api, ApiError, Credential, SettingsAnswer, UploadEdit, UploadQuery, rewrite_to_host,
};
use sha2::Digest;
use tokio_util::sync::CancellationToken;

const SERVER: &str = "http://127.0.0.1:8420";

fn qa_env() -> Option<HashMap<String, String>> {
    let path = std::env::var_os("MODLIGHT_QA_ENV")
        .map(PathBuf::from)
        .or_else(|| {
            let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
            loop {
                let candidate = dir.join("_wzorzec").join("qa-accounts.env");
                if candidate.is_file() {
                    return Some(candidate);
                }
                if !dir.pop() {
                    return None;
                }
            }
        })?;
    let text = std::fs::read_to_string(path).ok()?;
    Some(
        text.lines()
            .filter(|line| !line.trim_start().starts_with('#'))
            .filter_map(|line| line.split_once('='))
            .map(|(k, v)| (k.trim().to_string(), v.trim().to_string()))
            .collect(),
    )
}

struct Qa {
    api: Api,
    user: Credential,
    admin_full: Credential,
    admin_write: Credential,
}

fn qa() -> Option<Qa> {
    let Some(env) = qa_env() else {
        eprintln!("reference server tests skipped: no _wzorzec/qa-accounts.env");
        return None;
    };
    let get = |key: &str| {
        env.get(key)
            .cloned()
            .unwrap_or_else(|| panic!("{key} missing in qa-accounts.env"))
    };
    Some(Qa {
        api: Api::new("0.7.7").unwrap(),
        user: Credential::new(SERVER, get("QA_APP1_TOKEN_WRITE")),
        admin_full: Credential::new(SERVER, get("QA_ADMIN_TOKEN_FULL")),
        admin_write: Credential::new(SERVER, get("QA_ADMIN_TOKEN_WRITE")),
    })
}

fn unique(prefix: &str) -> String {
    format!(
        "{prefix}-{}",
        signin::new_state()[..10].to_ascii_lowercase()
    )
}

/// A small PNG nobody else has uploaded: random pixels.
fn png_bytes(size: u32) -> Vec<u8> {
    let mut pixels = image::RgbaImage::new(size, size);
    let seed = signin::new_state();
    let seed = seed.as_bytes();
    for (i, pixel) in pixels.pixels_mut().enumerate() {
        let b = seed[i % seed.len()];
        *pixel = image::Rgba([b, b.wrapping_mul(3), (i % 251) as u8, 255]);
    }
    let mut out = std::io::Cursor::new(Vec::new());
    pixels.write_to(&mut out, image::ImageFormat::Png).unwrap();
    out.into_inner()
}

async fn upload(
    qa: &Qa,
    credential: &Credential,
    name: &str,
    bytes: Vec<u8>,
    folder: Option<&str>,
) -> modlight_api::Upload {
    let answer = qa
        .api
        .upload_bytes(credential, name, bytes, folder)
        .await
        .unwrap();
    assert!(
        (200..300).contains(&answer.status),
        "upload refused: {} {}",
        answer.status,
        answer.body
    );
    let response = answer.response.expect("upload answer");
    assert!(response.link().is_some());
    // Find the row the listing reports for it.
    let page = qa
        .api
        .get_uploads(
            credential,
            &UploadQuery {
                page: 1,
                per_page: 120,
                folder_id: folder.map(str::to_string),
                ..Default::default()
            },
        )
        .await
        .unwrap();
    page.items
        .unwrap_or_default()
        .into_iter()
        .find(|row| row.filename.as_deref() == Some(name))
        .expect("uploaded row listed")
}

#[tokio::test]
async fn me_identifies_tokens_and_refuses_strangers() {
    let Some(qa) = qa() else { return };

    let me = qa
        .api
        .get_account(&qa.user)
        .await
        .unwrap()
        .expect("account");
    assert!(me.tag.as_deref().is_some_and(|t| !t.is_empty()));
    assert!(!me.is_admin());
    let quota = me.quota.expect("quota");
    assert!(quota.used >= 0);

    let admin = qa
        .api
        .get_account(&qa.admin_full)
        .await
        .unwrap()
        .expect("admin");
    assert!(admin.is_admin());

    let stranger = Credential::new(SERVER, "not-a-real-token-xxxxxxxxxxxxxxxx");
    assert_eq!(qa.api.get_account(&stranger).await.unwrap(), None);
    assert_eq!(
        qa.api.get_folders(&stranger).await.unwrap_err(),
        ApiError::Unauthorized
    );

    let nowhere = Credential::new("http://127.0.0.1:9", "x");
    assert!(matches!(
        qa.api.get_account(&nowhere).await.unwrap_err(),
        ApiError::Transport(_)
    ));
}

#[tokio::test]
async fn folders_files_links_and_the_trash() {
    let Some(qa) = qa() else { return };
    let api = &qa.api;
    let me = &qa.user;

    // Folders: a parent and a child.
    let parent_name = unique("it-parent");
    let parent = api
        .create_folder(me, &parent_name, None)
        .await
        .unwrap()
        .expect("folder");
    let parent_id = parent.id.clone().unwrap();
    let child = api
        .create_folder(me, &unique("it-child"), Some(&parent_id))
        .await
        .unwrap()
        .expect("child");
    assert_eq!(child.parent_id.as_deref(), Some(parent_id.as_str()));

    let list = api.get_folders(me).await.unwrap();
    let folders = list.folders.unwrap_or_default();
    assert!(folders.iter().any(|f| f.id == parent.id));
    assert!(list.root_value.as_deref().is_some_and(|r| !r.is_empty()));

    // Rename and publish the parent.
    let renamed = api
        .rename_folder(me, &parent_id, &format!("{parent_name}-renamed"))
        .await
        .unwrap()
        .expect("renamed");
    assert_eq!(
        renamed.name.as_deref(),
        Some(format!("{parent_name}-renamed").as_str())
    );
    let public = api
        .set_folder_visibility(me, &parent_id, true)
        .await
        .unwrap()
        .expect("public");
    assert!(public.is_public);

    // A picture and a text file in the parent.
    let picture_name = format!("{}.png", unique("pic"));
    let picture = upload(&qa, me, &picture_name, png_bytes(96), Some(&parent_id)).await;
    let picture_id = picture.id.clone().unwrap();
    assert_eq!(picture.folder_id.as_deref(), Some(parent_id.as_str()));
    assert_eq!(picture.kind.as_deref(), Some("image"));
    assert!(picture.created_at.is_some());

    let text_name = format!("{}.txt", unique("note"));
    let text = upload(
        &qa,
        me,
        &text_name,
        b"hello from the mac port".to_vec(),
        Some(&parent_id),
    )
    .await;
    let text_id = text.id.clone().unwrap();

    // The thumbnail is fetched on the origin we hold a token for.
    let thumb_url = picture.thumb_url.clone().expect("thumb url");
    let thumb = api
        .get_thumbnail(me, &thumb_url)
        .await
        .unwrap()
        .expect("thumbnail bytes");
    assert!(image::load_from_memory(&thumb).is_ok());
    assert_eq!(api.get_thumbnail(me, "not a url").await.unwrap(), None);

    // Searching and filtering by kind.
    let found = api
        .get_uploads(
            me,
            &UploadQuery {
                page: 1,
                per_page: 30,
                search: Some(picture_name.clone()),
                kind: Some("image".into()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
    assert!(
        found
            .items
            .unwrap_or_default()
            .iter()
            .any(|row| row.id.as_deref() == Some(picture_id.as_str()))
    );
    assert!(found.per_page > 0);

    // Move the text file out to "no folder", then publish/hide both at once.
    let moved = api
        .edit_uploads(
            me,
            std::slice::from_ref(&text_id),
            &UploadEdit::new().move_to(None),
        )
        .await
        .unwrap();
    assert_eq!(moved.affected, 1);
    assert_eq!(moved.items.unwrap_or_default()[0].folder_id, None);

    let hidden = api
        .edit_uploads(
            me,
            &[picture_id.clone(), text_id.clone()],
            &UploadEdit::new().set_published(false),
        )
        .await
        .unwrap();
    assert_eq!(hidden.affected, 2);
    assert!(
        hidden
            .items
            .unwrap_or_default()
            .iter()
            .all(|row| !row.published)
    );

    // A vanity code, and the refusal a taken one earns.
    let code = unique("vanity");
    let coded = api
        .edit_uploads(
            me,
            std::slice::from_ref(&picture_id),
            &UploadEdit::new().set_code(&code),
        )
        .await
        .unwrap();
    assert_eq!(
        coded.items.unwrap_or_default()[0].code.as_deref(),
        Some(code.as_str())
    );
    let taken = api
        .edit_uploads(
            me,
            std::slice::from_ref(&text_id),
            &UploadEdit::new().set_code(&code),
        )
        .await
        .unwrap_err();
    assert!(taken.is_name_taken(), "expected code-taken, got {taken:?}");
    assert_eq!(taken.status(), Some(409));

    // Link gates: set, then clear.
    let gated = api
        .edit_uploads(
            me,
            std::slice::from_ref(&picture_id),
            &UploadEdit::new()
                .set_expiry(Some(chrono::Utc::now() + chrono::Duration::hours(24)))
                .set_max_views(Some(5))
                .set_password(Some("hunter22")),
        )
        .await
        .unwrap();
    let row = &gated.items.unwrap_or_default()[0];
    assert!(row.expires_at.is_some());
    assert_eq!(row.max_views, Some(5));
    assert!(row.has_password);
    let cleared = api
        .edit_uploads(
            me,
            std::slice::from_ref(&picture_id),
            &UploadEdit::new()
                .set_expiry(None)
                .set_max_views(None)
                .set_password(None),
        )
        .await
        .unwrap();
    let row = &cleared.items.unwrap_or_default()[0];
    assert_eq!(row.expires_at, None);
    assert_eq!(row.max_views, None);
    assert!(!row.has_password);

    // Conversion check and download, through the media base the drawer uses.
    let page_url = row.url.clone().expect("page url");
    let ext = row.ext.clone().unwrap_or_default();
    let media_base = page_url
        .strip_suffix(&format!(".{ext}"))
        .unwrap_or(&page_url)
        .to_string();
    let verdict = api
        .check_conversion(me, &format!("{media_base}/convert?to=jpg"))
        .await;
    assert!(verdict.ok, "conversion refused: {}", verdict.reason);
    let refused = api.check_conversion(me, "nonsense").await;
    assert_eq!(refused.reason, "missing");

    let target = tempfile::tempdir().unwrap();
    let path = target.path().join("download.png");
    api.download_to_file(me, &format!("{media_base}/download"), &path)
        .await
        .unwrap();
    assert!(image::load_from_memory(&std::fs::read(&path).unwrap()).is_ok());

    // Trash, look in the trash, restore, trash again and delete for good.
    assert!(api.trash(me, &picture_id).await.unwrap());
    let trash = api
        .get_uploads(
            me,
            &UploadQuery {
                page: 1,
                per_page: 120,
                trashed: true,
                ..Default::default()
            },
        )
        .await
        .unwrap();
    let trashed_row = trash
        .items
        .unwrap_or_default()
        .into_iter()
        .find(|row| row.id.as_deref() == Some(picture_id.as_str()))
        .expect("in the trash");
    assert_eq!(trashed_row.url, None, "a trashed row has no public link");

    let restored = api
        .delete_uploads(me, std::slice::from_ref(&picture_id), "restore")
        .await
        .unwrap();
    assert_eq!(restored.affected, 1);
    assert_eq!(restored.mode.as_deref(), Some("restore"));

    let nothing = api
        .delete_uploads(
            me,
            &["00000000-0000-0000-0000-000000000000".into()],
            "trash",
        )
        .await
        .unwrap();
    assert_eq!(nothing.affected, 0, "not ours: answered, nothing touched");

    // The folder goes with its contents; the loose text file is removed by hand.
    let gone = api.delete_folder(me, &parent_id, true).await.unwrap();
    assert!(gone.with_contents);
    assert!(gone.folders >= 2);
    assert!(gone.trashed >= 1);
    let purge = api
        .delete_uploads(me, &[picture_id.clone(), text_id.clone()], "trash")
        .await
        .unwrap();
    assert!(purge.affected >= 1);
    let purged = api
        .delete_uploads(me, &[picture_id, text_id], "permanent")
        .await
        .unwrap();
    assert_eq!(purged.affected, 2);
}

#[tokio::test]
async fn deleting_a_folder_alone_keeps_its_files() {
    let Some(qa) = qa() else { return };
    let api = &qa.api;
    let me = &qa.user;

    let folder = api
        .create_folder(me, &unique("it-keep"), None)
        .await
        .unwrap()
        .unwrap();
    let id = folder.id.unwrap();
    let file = upload(
        &qa,
        me,
        &format!("{}.png", unique("kept")),
        png_bytes(16),
        Some(&id),
    )
    .await;

    let result = api.delete_folder(me, &id, false).await.unwrap();
    assert!(!result.with_contents);
    assert_eq!(result.trashed, 0);

    let loose = api
        .get_uploads(
            me,
            &UploadQuery {
                page: 1,
                per_page: 120,
                folder_id: Some(modlight_api::ROOT_FOLDER.into()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
    assert!(
        loose
            .items
            .unwrap_or_default()
            .iter()
            .any(|row| row.id == file.id)
    );

    // A folder that does not exist is a refusal in the server's own words.
    let unknown_folder = api
        .rename_folder(me, "00000000-0000-0000-0000-000000000000", "x")
        .await
        .unwrap_err();
    assert!(
        matches!(&unknown_folder, ApiError::Refused { detail, .. } if !detail.is_empty()),
        "{unknown_folder:?}"
    );

    api.delete_uploads(me, &[file.id.clone().unwrap()], "trash")
        .await
        .unwrap();
    api.delete_uploads(me, &[file.id.unwrap()], "permanent")
        .await
        .unwrap();
}

#[tokio::test]
async fn duplicates_are_found_kept_and_counted_again() {
    let Some(qa) = qa() else { return };
    let api = &qa.api;
    let me = &qa.user;

    let bytes = png_bytes(24);
    let checksum = hex::encode(sha2::Sha256::digest(&bytes));
    let a = upload(
        &qa,
        me,
        &format!("{}.png", unique("dup-a")),
        bytes.clone(),
        None,
    )
    .await;
    let b = upload(&qa, me, &format!("{}.png", unique("dup-b")), bytes, None).await;

    let scan = api.get_duplicates(me).await.unwrap();
    let group = scan
        .groups
        .unwrap_or_default()
        .into_iter()
        .find(|g| g.checksum.as_deref() == Some(checksum.as_str()))
        .expect("the two copies form a set");
    assert_eq!(group.copies, 2);
    assert!(group.reclaimable > 0);
    let files = group.files.clone().unwrap_or_default();
    assert_eq!(files.len(), 2);
    assert_eq!(files[0].id, a.id, "oldest first");

    assert_eq!(
        api.keep_duplicate_sets(me, std::slice::from_ref(&group))
            .await
            .unwrap(),
        1
    );
    let scan = api.get_duplicates(me).await.unwrap();
    assert!(
        scan.groups
            .unwrap_or_default()
            .iter()
            .any(|g| g.checksum.as_deref() == Some(checksum.as_str()) && g.dismissed)
    );
    assert_eq!(
        api.count_duplicate_sets_again(me, std::slice::from_ref(&checksum))
            .await
            .unwrap(),
        1
    );
    assert_eq!(api.keep_duplicate_sets(me, &[]).await.unwrap(), 0);

    let ids = vec![a.id.unwrap(), b.id.unwrap()];
    api.delete_uploads(me, &ids, "trash").await.unwrap();
    api.delete_uploads(me, &ids, "permanent").await.unwrap();
}

