#[tokio::test]
async fn client_settings_are_versioned() {
    let Some(qa) = qa() else { return };
    let api = &qa.api;
    let me = &qa.user;

    let SettingsAnswer::Document(current) = api.client_settings(me, None).await.unwrap() else {
        panic!("the read was refused");
    };
    let document = serde_json::json!({ "schema": 1, "app": { "Language": "Automatic" } });

    // A write against a version that is not the current one is refused with the winner.
    let SettingsAnswer::Document(conflict) = api
        .client_settings(me, Some((&document, current.version + 1000)))
        .await
        .unwrap()
    else {
        panic!("expected a 409 answer");
    };
    assert!(conflict.conflict);
    assert_eq!(conflict.version, current.version);

    let SettingsAnswer::Document(saved) = api
        .client_settings(me, Some((&document, current.version)))
        .await
        .unwrap()
    else {
        panic!("the write was refused");
    };
    assert!(!saved.conflict);
    assert_eq!(saved.version, current.version + 1);
    assert!(saved.limit_bytes > 0);

    let SettingsAnswer::Document(read) = api.client_settings(me, None).await.unwrap() else {
        panic!("the read was refused");
    };
    assert_eq!(read.settings.get("schema"), Some(&serde_json::json!(1)));

    let stranger = Credential::new(SERVER, "not-a-real-token-xxxxxxxxxxxxxxxx");
    assert!(matches!(
        api.client_settings(&stranger, None).await.unwrap(),
        SettingsAnswer::Refused(401)
    ));
}

#[tokio::test]
async fn the_disk_report_needs_an_administrator_and_a_full_token() {
    let Some(qa) = qa() else { return };
    let api = &qa.api;

    let report = api.get_disk_report(&qa.admin_full).await.unwrap();
    assert!(report.driver.is_some());
    assert!(report.live_files >= 0);

    assert_eq!(
        api.get_disk_report(&qa.admin_write).await.unwrap_err(),
        ApiError::AdminForbidden
    );
    let user = api.get_disk_report(&qa.user).await.unwrap_err();
    assert!(
        user == ApiError::AdminForbidden || user == ApiError::NotSupported,
        "a regular account is refused: {user:?}"
    );
    let stranger = Credential::new(SERVER, "not-a-real-token-xxxxxxxxxxxxxxxx");
    assert_eq!(
        api.get_disk_report(&stranger).await.unwrap_err(),
        ApiError::Unauthorized
    );
}

#[tokio::test]
async fn short_links_and_their_refusals() {
    let Some(qa) = qa() else { return };
    let api = &qa.api;
    let me = &qa.user;

    let link = api
        .shorten(me, "https://example.com/from-the-mac-port", None)
        .await
        .unwrap();
    assert!(link.url.as_deref().is_some_and(|u| u.starts_with("http")));

    let custom = modlight_api::ShortLinkOptions {
        custom_code: Some(unique("short")),
        expires_in_days: Some(1),
        password: Some("pw-for-one-link".into()),
        use_user_code: true,
    };
    let named = api
        .shorten(me, "https://example.com/named", Some(&custom))
        .await
        .unwrap();
    assert!(
        named
            .url
            .unwrap()
            .contains(custom.custom_code.as_deref().unwrap())
    );

    let bad = api
        .shorten(me, "javascript:alert(1)", None)
        .await
        .unwrap_err();
    assert!(
        matches!(&bad, ApiError::Refused { reason: Some(r), .. } if r == "invalid-url"),
        "{bad:?}"
    );

    let root = modlight_api::ShortLinkOptions {
        custom_code: Some(unique("root")),
        use_user_code: false,
        ..Default::default()
    };
    let refused = api
        .shorten(me, "https://example.com/root", Some(&root))
        .await
        .unwrap_err();
    assert!(
        matches!(&refused, ApiError::Refused { reason: Some(r), .. } if r == "root-not-allowed"),
        "{refused:?}"
    );
}

