/// Play the authorize page: post `body` to the loopback port like the browser does.
fn post_like_the_page(port: u16, origin: &str, body: &str) -> String {
    let mut stream = TcpStream::connect(("127.0.0.1", port)).unwrap();
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .unwrap();
    write!(
        stream,
        "POST / HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nOrigin: {origin}\r\nContent-Type: text/plain;charset=UTF-8\r\nContent-Length: {}\r\n\r\n{body}",
        body.len()
    )
    .unwrap();
    let mut answer = String::new();
    let _ = stream.read_to_string(&mut answer);
    answer
}

fn preflight(port: u16, origin: &str) -> String {
    let mut stream = TcpStream::connect(("127.0.0.1", port)).unwrap();
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .unwrap();
    write!(
        stream,
        "OPTIONS / HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nOrigin: {origin}\r\nAccess-Control-Request-Method: POST\r\nAccess-Control-Request-Private-Network: true\r\n\r\n"
    )
    .unwrap();
    let mut answer = String::new();
    let _ = stream.read_to_string(&mut answer);
    answer
}

#[tokio::test]
async fn the_loopback_listener_ignores_strangers_and_takes_our_answer() {
    let listener = LoopbackListener::bind(SERVER).await.unwrap();
    let port = listener.port();
    let state = signin::new_state();
    let cancel = CancellationToken::new();

    let expected = state.clone();
    let browser = std::thread::spawn(move || {
        // CORS, the private-network grant included, goes to the server's origin only.
        let foreign = preflight(port, "https://evil.example");
        assert!(foreign.starts_with("HTTP/1.1 204"));
        assert!(!foreign.contains("Access-Control-Allow-Origin"));
        assert!(!foreign.to_ascii_lowercase().contains("private-network"));
        let ours = preflight(port, SERVER);
        assert!(ours.contains(&format!("Access-Control-Allow-Origin: {SERVER}")));
        assert!(ours.contains("Access-Control-Allow-Private-Network: true"));

        // A GET is not a handoff; junk and a wrong state are answered and ignored.
        let mut get = TcpStream::connect(("127.0.0.1", port)).unwrap();
        write!(get, "GET / HTTP/1.1\r\nHost: x\r\n\r\n").unwrap();
        let mut answer = String::new();
        let _ = get.read_to_string(&mut answer);
        assert!(answer.starts_with("HTTP/1.1 405"));
        assert!(post_like_the_page(port, SERVER, "not json").starts_with("HTTP/1.1 204"));
        let wrong = format!(r#"{{"state":"{}","token":"attacker"}}"#, "x".repeat(32));
        assert!(
            post_like_the_page(port, "https://evil.example", &wrong).starts_with("HTTP/1.1 204")
        );

        let right = format!(r#"{{"state":"{expected}","token":"the-real-token"}}"#);
        assert!(post_like_the_page(port, SERVER, &right).starts_with("HTTP/1.1 204"));
    });

    let handoff = tokio::time::timeout(Duration::from_secs(20), listener.wait_for(&state, &cancel))
        .await
        .expect("handoff in time")
        .expect("not cancelled");
    assert_eq!(handoff.token.as_deref(), Some("the-real-token"));
    browser.join().unwrap();

    // Cancelling ends the wait.
    let other = LoopbackListener::bind(SERVER).await.unwrap();
    let stop = CancellationToken::new();
    stop.cancel();
    assert_eq!(other.wait_for("whatever", &stop).await, None);
}

#[tokio::test]
async fn browser_sign_in_end_to_end() {
    let Some(qa) = qa() else { return };
    let token = qa.user.token.clone();
    let cancel = CancellationToken::new();

    // The "browser": parse the authorize link and deliver the token like the page does.
    let open = move |url: &str| {
        let parsed = url::Url::parse(url).unwrap();
        assert_eq!(parsed.path(), "/authorize");
        let query: HashMap<String, String> = parsed.query_pairs().into_owned().collect();
        let port: u16 = query["port"].parse().unwrap();
        let state = query["state"].clone();
        assert_eq!(state.len(), 32);
        assert_eq!(query["name"], "Modlight on QA Mac");
        std::thread::spawn(move || {
            let body = format!(r#"{{"state":"{state}","token":"{token}"}}"#);
            post_like_the_page(port, SERVER, &body);
        });
    };

    let signed = signin::sign_in_with_browser(
        &qa.api,
        "http://127.0.0.1:8420/dashboard",
        "Modlight on QA Mac",
        open,
        &cancel,
    )
    .await
    .unwrap();
    assert_eq!(signed.origin, SERVER);
    assert!(signed.account.tag.is_some());

    // A refusal in the browser.
    let denied = signin::sign_in_with_browser(
        &qa.api,
        SERVER,
        "Modlight on QA Mac",
        |url: &str| {
            let parsed = url::Url::parse(url).unwrap();
            let query: HashMap<String, String> = parsed.query_pairs().into_owned().collect();
            let port: u16 = query["port"].parse().unwrap();
            let state = query["state"].clone();
            std::thread::spawn(move || {
                post_like_the_page(
                    port,
                    SERVER,
                    &format!(r#"{{"state":"{state}","error":"access_denied"}}"#),
                );
            });
        },
        &cancel,
    )
    .await
    .unwrap_err();
    assert_eq!(denied, signin::SignInFailure::Denied(None));

    // The manual route, and its refusals.
    assert!(
        signin::use_token(&qa.api, SERVER, &format!("  {}  ", qa.user.token), &cancel)
            .await
            .is_ok()
    );
    assert_eq!(
        signin::use_token(&qa.api, SERVER, "bad token with spaces", &cancel)
            .await
            .unwrap_err(),
        signin::SignInFailure::NoToken
    );
    assert_eq!(
        signin::use_token(
            &qa.api,
            SERVER,
            "not-a-real-token-xxxxxxxxxxxxxxxx",
            &cancel
        )
        .await
        .unwrap_err(),
        signin::SignInFailure::TokenRejected
    );
    assert_eq!(
        signin::use_token(&qa.api, "ftp://nope", "abc", &cancel)
            .await
            .unwrap_err(),
        signin::SignInFailure::InvalidHost
    );
}
